const { Conf } = require('@dotenvx/tooling')
const { derive, keypair } = require('@dotenvx/primitives')
const settings = require('./settings')
const backends = {
  darwin: require('./macosKeychain'),
  win32: require('./windowsCredentialManager'),
  linux: require('./linuxSecretService')
}

function disabled (options, env) {
  return options.armor === false || options.noArmor === true || env.DOTENVX_NO_ARMOR === 'true'
}

function device (env) {
  const store = new Conf({
    cwd: env.DOTENVX_CONFIG || undefined,
    projectName: 'dotenvx',
    configName: '.device-key',
    projectSuffix: '',
    fileExtension: '',
    encryptionKey: 'dotenvxpro dotenvxpro dotenvxpro'
  })
  let privateKey = store.get('private_key/1')
  if (!privateKey) {
    privateKey = keypair().privateKey
    store.set('private_key/1', privateKey)
  }
  return derive(privateKey)
}

function resolve (options, env, saved) {
  if (!options.token && (saved.ON === 'false' || !saved.USERNAME)) return null
  let token = options.token
  if (!token) {
    try { token = backends[process.platform]?.get('DOTENVX_ARMOR_TOKEN') } catch {}
    token ||= saved.TOKEN
  }
  if (!token) return null
  return {
    ...options,
    hostname: options.hostname || saved.HOSTNAME || 'https://armor.dotenvx.com',
    token,
    devicePublicKey: options.devicePublicKey || device(env)
  }
}

function complete (options) {
  return options.token && options.hostname && options.devicePublicKey
}

async function session (options = {}) {
  const env = options.processEnv || process.env
  if (disabled(options, env)) return null
  if (complete(options)) return options
  const saved = {}
  for (const key of ['HOSTNAME', 'ON', 'USERNAME', 'TOKEN']) saved[key] = await settings.get(`DOTENVX_ARMOR_${key}`, env)
  return resolve(options, env, saved)
}

session.sync = function (options = {}) {
  const env = options.processEnv || process.env
  if (disabled(options, env)) return null
  if (complete(options)) return options
  const saved = {}
  for (const key of ['HOSTNAME', 'ON', 'USERNAME', 'TOKEN']) saved[key] = settings.getSync(`DOTENVX_ARMOR_${key}`, env)
  return resolve(options, env, saved)
}

module.exports = session
